import os,subprocess,sys,base64,shutil
API='/var/www/vibkaptur/public/api'; SCR='/var/www/vibkaptur/scripts'
F={'vibk_termo_srv.py':'','termo.php':'','termoimg.php':'','termodl.php':''}
for n,c in F.items():
    open('/tmp/_'+n,'wb').write(base64.b64decode(c))
    r=subprocess.run(['python3','-m','py_compile','/tmp/_'+n] if n.endswith('.py') else ['php','-l','/tmp/_'+n],capture_output=True)
    if r.returncode!=0: print('FALLO de sintaxis en',n,'. NO SE HA TOCADO NADA'); sys.exit(1)
sp=os.path.join(API,'subir.php'); s=open(sp,encoding='utf-8').read()
OLD="if(strpos($head,'%PDF')===0){"
NEW="""if(strpos($head,'%PDF')===0 && isset($_POST['k']) && $_POST['k']==='termo'){
  // PDF del informe de termografias: va aparte, no pisa el de vibraciones
  $tdir=$dir.'/termo';
  if(!is_dir($tdir)) mkdir($tdir,0775,true);
  if(!move_uploaded_file($tmp,$tdir.'/pending.pdf')){echo json_encode(array('ok'=>false,'e'=>'save'));exit;}
  echo json_encode(array('ok'=>true,'kind'=>'termopdf','bytes'=>filesize($tdir.'/pending.pdf'),'cliente'=>$c));
  exit;
}
"""+OLD
if "'kind'=>'termopdf'" in s: print('subir.php ya estaba actualizado')
else:
    if s.count(OLD)!=1: print('FALLO: subir.php no es como se esperaba. NO SE HA TOCADO NADA'); sys.exit(1)
    open('/tmp/_subir.php','w',encoding='utf-8').write(s.replace(OLD,NEW))
    if subprocess.run(['php','-l','/tmp/_subir.php'],capture_output=True).returncode!=0: print('FALLO de sintaxis en subir.php. NO SE HA TOCADO NADA'); sys.exit(1)
    shutil.copy2(sp,sp+'.bak9'); st=os.stat(sp); shutil.copyfile('/tmp/_subir.php',sp); os.chmod(sp,st.st_mode&0o7777); os.chown(sp,st.st_uid,st.st_gid)
def put(path,src,ref):
    st=os.stat(ref); shutil.copyfile(src,path); os.chown(path,st.st_uid,st.st_gid); os.chmod(path,st.st_mode&0o7777)
put(os.path.join(SCR,'vibk_termo_srv.py'),'/tmp/_vibk_termo_srv.py',os.path.join(SCR,'vibk_publish_srv.py'))
for n in ('termo.php','termoimg.php','termodl.php'): put(os.path.join(API,n),'/tmp/_'+n,os.path.join(API,'revisar.php'))
